import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum PrintColor {
  BW = 'Black & White',
  COLOR = 'Color'
}

export enum PagesPerSheet {
  ONE = 1,
  TWO = 2,
  FOUR = 4
}

export enum Orientation {
  PORTRAIT = 'Portrait',
  LANDSCAPE = 'Landscape'
}

export enum JobStatus {
  PENDING = 'Pending',
  VERIFIED = 'Verified',
  PRINTING = 'Printing',
  COMPLETED = 'Completed'
}

export interface PrintJob {
  id: string;
  filename: string;
  fileUrl: string; // Blob URL (In-memory)
  fileType: string;
  numCopies: number;
  color: PrintColor;
  pagesPerSheet: PagesPerSheet;
  pageRange: string;
  orientation: Orientation;
  otp: string;
  status: JobStatus;
  timestamp: number;
  estimatedCost: number;
}

export interface SystemState {
  jobs: PrintJob[];
}

import React, { useState, useEffect, useCallback } from 'react';
import { PrintJob, JobStatus } from './types';
import StudentPortal from './components/StudentPortal';
import ShopOwnerDashboard from './components/ShopOwnerDashboard';
import Header from './components/Header';
import { GoogleGenAI } from "@google/genai";

const App: React.FC = () => {
  const [view, setView] = useState<'student' | 'owner'>('student');
  const [jobs, setJobs] = useState<PrintJob[]>([]);

  // Simulation of "Real-time" backend
  const addJob = useCallback((job: PrintJob) => {
    setJobs(prev => [...prev, job]);
  }, []);

  const updateJobStatus = useCallback((id: string, status: JobStatus) => {
    setJobs(prev => prev.map(job => 
      job.id === id ? { ...job, status } : job
    ));

    // Auto-delete mechanism simulation:
    // If completed, remove the blob URL and delete from state after a short delay
    if (status === JobStatus.COMPLETED) {
      setTimeout(() => {
        setJobs(prev => {
          const target = prev.find(j => j.id === id);
          if (target?.fileUrl) {
            URL.revokeObjectURL(target.fileUrl);
          }
          return prev.filter(job => job.id !== id);
        });
      }, 5000); // 5 second buffer before immediate destruction
    }
  }, []);

  const removeJob = useCallback((id: string) => {
    setJobs(prev => {
      const target = prev.find(j => j.id === id);
      if (target?.fileUrl) {
        URL.revokeObjectURL(target.fileUrl);
      }
      return prev.filter(job => job.id !== id);
    });
  }, []);

  return (
    <div className="min-h-screen flex flex-col no-print">
      <Header view={view} setView={setView} />

      <main className="flex-grow container mx-auto px-4 py-8">
        {view === 'student' ? (
          <StudentPortal onJobCreated={addJob} />
        ) : (
          <ShopOwnerDashboard 
            jobs={jobs} 
            onUpdateStatus={updateJobStatus} 
            onRemoveJob={removeJob}
          />
        )}
      </main>

      <footer className="bg-white border-t py-6 text-center text-slate-500 text-sm">
        <p>&copy; 2024 XeroxStream. Privacy-First Printing Architecture.</p>
        <p className="mt-1">Files are processed in-memory and never stored permanently.</p>
      </footer>
    </div>
  );
};

export default App;

