import React, { useState, useRef } from 'react';
import { PrintJob, PrintColor, PagesPerSheet, Orientation, JobStatus } from '../types';
import { Upload, FileText, Settings, CheckCircle2 } from 'lucide-react';
import { GoogleGenAI } from "@google/genai";

interface StudentPortalProps {
  onJobCreated: (job: PrintJob) => void;
}

const StudentPortal: React.FC<StudentPortalProps> = ({ onJobCreated }) => {
  const [file, setFile] = useState<File | null>(null);
  const [settings, setSettings] = useState({
    copies: 1,
    color: PrintColor.BW,
    pagesPerSheet: PagesPerSheet.ONE,
    pageRange: 'All',
    orientation: Orientation.PORTRAIT
  });
  const [createdJob, setCreatedJob] = useState<PrintJob | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysisNote, setAnalysisNote] = useState("");
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const selectedFile = e.target.files[0];
      setFile(selectedFile);
      analyzeWithGemini(selectedFile);
    }
  };

  const analyzeWithGemini = async (selectedFile: File) => {
    setIsAnalyzing(true);
    try {
      // In a real app, we'd pass a preview image of the PDF/Doc
      // For this demo, we'll ask Gemini to generate "printing tips" based on the filename and metadata
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Analyze this print request: Filename "${selectedFile.name}", size ${Math.round(selectedFile.size / 1024)}KB. 
                  Provide a 1-sentence tip for printing this document optimally at a Xerox shop.`
      });
      setAnalysisNote(response.text || "Ready to print.");
    } catch (err) {
      console.error("Gemini analysis failed", err);
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!file) return;

    // Generate in-memory URL (stays in RAM only)
    const fileUrl = URL.createObjectURL(file);
    const otp = Math.floor(1000 + Math.random() * 9000).toString();

    const newJob: PrintJob = {
      id: Math.random().toString(36).substr(2, 9),
      filename: file.name,
      fileUrl,
      fileType: file.type,
      numCopies: settings.copies,
      color: settings.color,
      pagesPerSheet: settings.pagesPerSheet,
      pageRange: settings.pageRange,
      orientation: settings.orientation,
      otp,
      status: JobStatus.PENDING,
      timestamp: Date.now(),
      estimatedCost: (settings.copies * 2) // Simple logic: 2 INR per page
    };

    onJobCreated(newJob);
    setCreatedJob(newJob);
  };

  if (createdJob) {
    return (
      <div className="max-w-md mx-auto bg-white rounded-2xl shadow-xl overflow-hidden animate-in fade-in zoom-in duration-300">
        <div className="bg-indigo-600 p-8 text-center">
          <div className="bg-white/20 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
            <CheckCircle2 className="text-white w-10 h-10" />
          </div>
          <h2 className="text-2xl font-bold text-white mb-2">Submission Successful!</h2>
          <p className="text-indigo-100">Show this OTP to the shop owner to start printing.</p>
        </div>

        <div className="p-8 text-center">
          <div className="text-sm text-slate-500 uppercase tracking-widest font-semibold mb-2">ONE-TIME PASSCODE</div>
          <div className="text-6xl font-black text-indigo-600 tracking-tighter mb-6 bg-indigo-50 py-4 rounded-xl">
            {createdJob.otp}
          </div>

          <div className="space-y-4 text-left border-t pt-6">
            <div className="flex justify-between text-sm">
              <span className="text-slate-500">Document</span>
              <span className="font-medium truncate max-w-[200px]">{createdJob.filename}</span>
            </div>
            <div className="flex justify-between text-sm">
              <span className="text-slate-500">Settings</span>
              <span className="font-medium">{createdJob.color}, {createdJob.numCopies} copies</span>
            </div>
            <div className="flex justify-between text-sm border-t pt-4">
              <span className="text-slate-500 font-bold">Estimated Total</span>
              <span className="font-bold text-indigo-600">₹{createdJob.estimatedCost}</span>
            </div>
          </div>

          <button 
            onClick={() => { setFile(null); setCreatedJob(null); }}
            className="w-full mt-8 bg-slate-900 text-white py-3 rounded-xl font-semibold hover:bg-slate-800 transition-colors"
          >
            Print Another Document
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-xl mx-auto">
      <div className="mb-8 text-center">
        <h1 className="text-3xl font-bold text-slate-900 mb-2">Smart Printing, Simplified</h1>
        <p className="text-slate-600">Upload your documents and print them instantly without sharing any personal info.</p>
      </div>

      <div className="bg-white rounded-2xl shadow-lg p-6 md:p-8">
        <form onSubmit={handleSubmit} className="space-y-8">
          {/* File Upload Area */}
          <div 
            onClick={() => fileInputRef.current?.click()}
            className={`border-2 border-dashed rounded-xl p-8 transition-all cursor-pointer text-center ${
              file ? 'border-indigo-400 bg-indigo-50' : 'border-slate-200 hover:border-indigo-300 hover:bg-slate-50'
            }`}
          >
            <input 
              type="file" 
              ref={fileInputRef} 
              onChange={handleFileChange} 
              className="hidden" 
              accept=".pdf,.jpg,.jpeg,.png"
            />
            {file ? (
              <div className="flex flex-col items-center">
                <div className="bg-indigo-600 p-3 rounded-lg mb-3">
                  <FileText className="text-white w-8 h-8" />
                </div>
                <p className="font-medium text-slate-900">{file.name}</p>
                <p className="text-xs text-slate-500 mt-1">{(file.size / 1024 / 1024).toFixed(2)} MB</p>

                {isAnalyzing ? (
                  <div className="mt-4 flex items-center gap-2 text-xs text-indigo-600 animate-pulse">
                    <span className="w-2 h-2 bg-indigo-600 rounded-full"></span>
                    Gemini AI is analyzing document...
                  </div>
                ) : analysisNote && (
                  <div className="mt-4 bg-white/60 p-2 rounded text-xs text-indigo-700 italic border border-indigo-100">
                    " {analysisNote} "
                  </div>
                )}
              </div>
            ) : (
              <div className="flex flex-col items-center">
                <div className="bg-slate-100 p-4 rounded-full mb-4">
                  <Upload className="text-slate-400 w-10 h-10" />
                </div>
                <p className="text-lg font-semibold text-slate-700">Tap to select your document</p>
                <p className="text-sm text-slate-400 mt-2">PDF, Images accepted. Max 20MB.</p>
              </div>
            )}
          </div>

          {/* Settings Section */}
          <div className="space-y-6">
            <div className="flex items-center gap-2 text-slate-900 font-bold border-b pb-2">
              <Settings className="w-5 h-5 text-indigo-600" />
              <span>Print Settings</span>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-sm font-semibold text-slate-700">Number of Copies</label>
                <input 
                  type="number" 
                  min="1" 
                  value={settings.copies}
                  onChange={(e) => setSettings({...settings, copies: parseInt(e.target.value) || 1})}
                  className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                />
              </div>

              <div className="space-y-2">
                <label className="text-sm font-semibold text-slate-700">Color Mode</label>
                <select 
                  value={settings.color}
                  onChange={(e) => setSettings({...settings, color: e.target.value as PrintColor})}
                  className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                >
                  <option value={PrintColor.BW}>Black & White (₹2)</option>
                  <option value={PrintColor.COLOR}>Full Color (₹10)</option>
                </select>
              </div>

              <div className="space-y-2">
                <label className="text-sm font-semibold text-slate-700">Pages per Sheet</label>
                <div className="flex gap-2">
                  {[1, 2, 4].map((num) => (
                    <button
                      key={num}
                      type="button"
                      onClick={() => setSettings({...settings, pagesPerSheet: num as PagesPerSheet})}
                      className={`flex-1 py-2 text-sm font-medium border rounded-lg transition-all ${
                        settings.pagesPerSheet === num 
                          ? 'bg-indigo-600 border-indigo-600 text-white shadow-md' 
                          : 'bg-white border-slate-200 text-slate-600 hover:border-indigo-300'
                      }`}
                    >
                      {num}
                    </button>
                  ))}
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-sm font-semibold text-slate-700">Page Range</label>
                <input 
                  type="text" 
                  placeholder="e.g. 1-5, 10"
                  value={settings.pageRange}
                  onChange={(e) => setSettings({...settings, pageRange: e.target.value})}
                  className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                />
              </div>
            </div>
          </div>

          <button 
            type="submit" 
            disabled={!file}
            className={`w-full py-4 rounded-xl font-bold text-lg transition-all transform active:scale-[0.98] ${
              file 
                ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-200 hover:bg-indigo-700' 
                : 'bg-slate-200 text-slate-400 cursor-not-allowed'
            }`}
          >
            Generate Print OTP
          </button>
        </form>
      </div>
    </div>
  );
};

export default StudentPortal;

import React, { useState } from 'react';
import { PrintJob, JobStatus } from '../types';
import { RefreshCcw, Search, Clock, ShieldCheck, Printer, Trash2 } from 'lucide-react';
import JobCard from './JobCard';

