      {/* Queue List */}
      <div className="space-y-4">
        {filteredJobs.length === 0 ? (
          <div className="bg-white rounded-2xl border-2 border-dashed border-slate-200 py-20 text-center">
            <div className="text-slate-400 mb-2">No active print requests.</div>
            <p className="text-sm text-slate-400">Requests will appear here as students scan the QR code.</p>
          </div>
