import React, { useState, useEffect, useCallback, useRef } from 'react';
import { PrintJob, JobStatus } from './types';
import StudentPortal from './components/StudentPortal';
import ShopOwnerDashboard from './components/ShopOwnerDashboard';
import Header from './components/Header';

const App: React.FC = () => {
  const [view, setView] = useState<'student' | 'owner'>('student');
  const [jobs, setJobs] = useState<PrintJob[]>([]);

  // Use BroadcastChannel to simulate a real-time backend/cloud sync
  // This allows different tabs (one student, one owner) to communicate
  const syncChannel = useRef<BroadcastChannel | null>(null);

  useEffect(() => {
    syncChannel.current = new BroadcastChannel('xerox_stream_sync');

    syncChannel.current.onmessage = (event) => {
      const { type, payload } = event.data;
      if (type === 'NEW_JOB') {
        setJobs(prev => [...prev, payload]);
      } else if (type === 'UPDATE_JOB') {
        setJobs(prev => prev.map(job => 
          job.id === payload.id ? { ...job, status: payload.status } : job
        ));
      } else if (type === 'REMOVE_JOB') {
        setJobs(prev => prev.filter(job => job.id !== payload.id));
      }
    };

    return () => syncChannel.current?.close();
  }, []);

  const addJob = useCallback((job: PrintJob) => {
    setJobs(prev => [...prev, job]);
    syncChannel.current?.postMessage({ type: 'NEW_JOB', payload: job });
  }, []);

  const updateJobStatus = useCallback((id: string, status: JobStatus) => {
    setJobs(prev => prev.map(job => 
      job.id === id ? { ...job, status } : job
    ));
    syncChannel.current?.postMessage({ type: 'UPDATE_JOB', payload: { id, status } });

    if (status === JobStatus.COMPLETED) {
      setTimeout(() => {
        setJobs(prev => {
          const target = prev.find(j => j.id === id);
          if (target?.fileUrl) URL.revokeObjectURL(target.fileUrl);
          return prev.filter(job => job.id !== id);
        });
        syncChannel.current?.postMessage({ type: 'REMOVE_JOB', payload: { id } });
      }, 10000); 
    }
  }, []);

  const removeJob = useCallback((id: string) => {
    setJobs(prev => {
      const target = prev.find(j => j.id === id);
      if (target?.fileUrl) URL.revokeObjectURL(target.fileUrl);
      return prev.filter(job => job.id !== id);
    });
    syncChannel.current?.postMessage({ type: 'REMOVE_JOB', payload: { id } });
  }, []);

  return (
    <div className="min-h-screen flex flex-col no-print bg-slate-50">
      <Header view={view} setView={setView} />

      <main className="flex-grow container mx-auto px-4 py-6 md:py-10">
        {view === 'student' ? (
          <StudentPortal onJobCreated={addJob} />
        ) : (
          <ShopOwnerDashboard 
            jobs={jobs} 
            onUpdateStatus={updateJobStatus} 
            onRemoveJob={removeJob}
          />
        )}
      </main>

      <footer className="bg-white border-t py-6 text-center text-slate-400 text-xs px-4">
        <p className="font-medium">XeroxStream Hybrid-Cloud Architecture</p>
        <p className="mt-1">Encrypted in-memory processing. Open this app in two tabs to see live sync!</p>
      </footer>
    </div>
  );
};

export default App;

