              <span className={`text-xs font-bold uppercase tracking-wider ${step >= i ? 'text-indigo-600' : 'text-slate-400'}`}>
                {i === 1 ? 'Upload' : 'Settings'}
              </span>
              {i === 1 && <div className={`w-12 h-0.5 rounded ${step > 1 ? 'bg-indigo-600' : 'bg-slate-200'}`} />}
            </div>
